<?php

declare(strict_types=1);

namespace App\Models;

/**
 * customer_list: schools and other organizations (they do not log in).
 * cl_id is a UUIDv7 generated by App\Services\CustomerService.
 * school_status PUBLIC (sekolah negeri) means the treasurer is a government treasurer (affects tax withholding).
 */
class CustomerModel extends BaseModel
{
    public const SCHOOL_STATUSES = ['PUBLIC' => 'Public school', 'PRIVATE' => 'Private school'];

    protected $table         = 'customer_list';
    protected array $lowercase = ['cl_organization_name']; // stored lower case, shown with up()
    protected $allowedFields = [
        'cl_id', 'cl_organization_name', 'npsn', 'school_level_id', 'school_status', 'cl_tax_id', 'cl_email', 'cl_phone',
        'default_payment_term_id', 'credit_limit', 'is_active',
    ];
    protected array $nullable = [
        'npsn', 'school_level_id', 'school_status', 'cl_tax_id', 'cl_email', 'cl_phone', 'default_payment_term_id', 'credit_limit',
    ];
    protected array $fieldLabels = [
        'cl_id'                   => 'Customer ID',
        'npsn'                    => 'NPSN',
        'school_level_id'         => 'School level',
        'school_status'           => 'School status',
        'cl_tax_id'               => 'NPWP',
        'default_payment_term_id' => 'Default payment terms',
    ];

    protected array $referencedBy = [
        'client_proposal_list' => 'customer_id',
        'invoice'              => 'customer_id',
    ];

    protected $validationRules = [
        'cl_id'                   => 'required|exact_length[36]|is_unique[customer_list.cl_id,id,{id}]',
        'cl_organization_name'    => 'required|max_length[200]',
        'npsn'                    => 'permit_empty|exact_length[8]|numeric|is_unique[customer_list.npsn,id,{id}]',
        'school_level_id'         => 'permit_empty|is_natural_no_zero|is_not_unique[school_level.id]',
        'school_status'           => 'permit_empty|in_list[PUBLIC,PRIVATE]',
        'cl_tax_id'               => 'permit_empty|max_length[32]|npwp',
        'cl_email'                => 'permit_empty|max_length[255]|valid_email',
        'cl_phone'                => 'permit_empty|max_length[32]|phone',
        'default_payment_term_id' => 'permit_empty|is_natural_no_zero|is_not_unique[payment_terms.id]',
        'credit_limit'            => 'permit_empty|decimal|greater_than_equal_to[0]',
        'is_active'               => 'permit_empty|in_list[0,1]',
    ];

    protected $validationMessages = [
        'cl_organization_name' => ['required' => 'Organization / school name is required.'],
        'npsn'                 => [
            'exact_length' => 'NPSN must be exactly 8 digits.',
            'numeric'      => 'NPSN must be exactly 8 digits.',
            'is_unique'    => 'Another customer already has this NPSN.',
        ],
    ];

    /**
     * List query with search and filters, joined with school level and payment term.
     *
     * @param array{q?: string, status?: string, level?: string, school_status?: string, rep?: string} $filters
     *        rep: a sales rep id, or 'mine' with $myRepId.
     * @param int|null $myRepId Sales rep linked to the current user (for rep = 'mine').
     *
     * @return $this
     */
    public function search(array $filters, ?int $myRepId = null): self
    {
        $this->select('customer_list.*, payment_terms.code AS payment_term_code, school_level.name AS school_level_name')
            ->join('payment_terms', 'payment_terms.id = customer_list.default_payment_term_id', 'left')
            ->join('school_level', 'school_level.id = customer_list.school_level_id', 'left')
            ->orderBy('customer_list.cl_organization_name');

        $q = trim((string) ($filters['q'] ?? ''));

        if ($q !== '') {
            $this->groupStart()
                ->like('customer_list.cl_organization_name', $q)
                ->orLike('customer_list.npsn', $q)
                ->orLike('customer_list.cl_id', $q)
                ->orLike('customer_list.cl_tax_id', $q)
                ->orLike('customer_list.cl_email', $q)
                ->orLike('customer_list.cl_phone', $q)
                ->groupEnd();
        }

        $status = $filters['status'] ?? '';

        if ($status === 'active' || $status === 'inactive') {
            $this->where('customer_list.is_active', $status === 'active' ? 1 : 0);
        }

        if (($filters['level'] ?? '') !== '') {
            $this->where('customer_list.school_level_id', (int) $filters['level']);
        }

        if (in_array($filters['school_status'] ?? '', ['PUBLIC', 'PRIVATE'], true)) {
            $this->where('customer_list.school_status', $filters['school_status']);
        }

        $rep   = $filters['rep'] ?? '';
        $repId = $rep === 'mine' ? ($myRepId ?? 0) : (int) $rep;

        if ($rep !== '') {
            $this->whereIn('customer_list.id', static function ($builder) use ($repId) {
                return $builder->select('customer_id')->from('customer_sales_rep')->where('sales_rep_id', $repId);
            });
        }

        return $this;
    }
}
